local SachetMaker = {}
local PRODUCTS = {
    iron_sachet = { name = "Železni voščena vrečka", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni voščena vrečka za glasbila." },
    bronze_sachet = { name = "Bronast voščena vrečka", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast voščena vrečka za fino glasbo." },
    silver_sachet = { name = "Srebrn voščena vrečka", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn voščena vrečka za plemiške glasbenike." },
    gilded_sachet = { name = "Pozlačen voščena vrečka", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen voščena vrečka za dvorne glasbenike." },
    jewel_set_sachet = { name = "Draguljast voščena vrečka", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast voščena vrečka za kraljevske glasbenike." },
    royal_sovereign_sachet = { name = "Kraljevski suveren voščena vrečka", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren voščena vrečka z biseri za krono." },
}
local BUILDINGS = {
    sachet_workshop = { name = "Sachet delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    sachet_house = { name = "Sachet hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_sachet_atelier = { name = "Mojstrski sachet atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_sachet_palace = { name = "Suverena sachet palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SachetMaker.ironStock = 10; SachetMaker.bronzeStock = 8; SachetMaker.woodStock = 12; SachetMaker.leatherStock = 18; SachetMaker.silverStock = 8; SachetMaker.goldStock = 6; SachetMaker.jewelStock = 4; SachetMaker.pearlStock = 4
SachetMaker.productStock = {}; SachetMaker.buildings = {}; SachetMaker.maker = nil; SachetMaker.activeMaking = {}; SachetMaker.totalProducts = 0; SachetMaker.dayTimer = 0
function SachetMaker.init() SachetMaker.ironStock=10; SachetMaker.bronzeStock=8; SachetMaker.woodStock=12; SachetMaker.leatherStock=18; SachetMaker.silverStock=8; SachetMaker.goldStock=6; SachetMaker.jewelStock=4; SachetMaker.pearlStock=4; SachetMaker.productStock={}; SachetMaker.buildings={}; SachetMaker.maker=nil; SachetMaker.activeMaking={}; SachetMaker.totalProducts=0; SachetMaker.dayTimer=0; print("[SachetMaker] Royal Sachet Maker System initialized (6 products, 4 buildings)") end
function SachetMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SachetMaker.maker={name=n or ("Vrečkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrečkar najet: %s (spretnost: %d)",SachetMaker.maker.name,s),"success") end; return true end
function SachetMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SachetMaker.build(id) local ok,e=SachetMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SachetMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SachetMaker.getQualityBonus() local b=0; for _,bd in ipairs(SachetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SachetMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SachetMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SachetMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SachetMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SachetMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SachetMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SachetMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SachetMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SachetMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SachetMaker.buildings==0 then return false,"Potrebna vrečkarska delavnica" end; if not SachetMaker.maker then return false,"Potreben vreckar" end; return true end
function SachetMaker.make(pt,qty) qty=qty or 1; local ok,e=SachetMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SachetMaker.ironStock=SachetMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SachetMaker.bronzeStock=SachetMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SachetMaker.woodStock=SachetMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SachetMaker.leatherStock=SachetMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SachetMaker.silverStock=SachetMaker.silverStock-d.silverCost*qty end; if d.goldCost then SachetMaker.goldStock=SachetMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SachetMaker.jewelStock=SachetMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SachetMaker.pearlStock=SachetMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SachetMaker.maker then t=math.max(1,t-math.floor(SachetMaker.maker.skill/13)) end; table.insert(SachetMaker.activeMaking,{id="sachet_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SachetMaker.completeMaking(m) local q=1.0+(SachetMaker.getQualityBonus()/100); if SachetMaker.maker then q=q+(SachetMaker.maker.skill/140) end; q=math.min(2.5,q); SachetMaker.productStock[m.productType]=(SachetMaker.productStock[m.productType] or 0)+m.quantity; SachetMaker.totalProducts=SachetMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SachetMaker.maker then SachetMaker.maker.itemsMade=SachetMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SachetMaker.maker.skill=math.min(100,SachetMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrečka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sachet.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SachetMaker.update(dt) if not _G.state then return end; SachetMaker.dayTimer=SachetMaker.dayTimer+dt; if SachetMaker.dayTimer>=30 then SachetMaker.dayTimer=0; for i=#SachetMaker.activeMaking,1,-1 do local m=SachetMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SachetMaker.completeMaking(m); table.remove(SachetMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SachetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SachetMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SachetMaker.getStats() return {ironStock=SachetMaker.ironStock,bronzeStock=SachetMaker.bronzeStock,woodStock=SachetMaker.woodStock,leatherStock=SachetMaker.leatherStock,silverStock=SachetMaker.silverStock,goldStock=SachetMaker.goldStock,jewelStock=SachetMaker.jewelStock,pearlStock=SachetMaker.pearlStock,productStock=SachetMaker.productStock,numBuildings=#SachetMaker.buildings,hasMaker=SachetMaker.maker~=nil,makerName=SachetMaker.maker and SachetMaker.maker.name or "—",makerSkill=SachetMaker.maker and SachetMaker.maker.skill or 0,activeMaking=#SachetMaker.activeMaking,totalProducts=SachetMaker.totalProducts} end
return SachetMaker
